CREATE TABLE IF NOT EXISTS "Stores" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Code" text NOT NULL,
  "Name" text NOT NULL,
  "Type" text NOT NULL,
  "BusinessTitle" text NOT NULL,
  "Currency" text NOT NULL,
  "Active" boolean NOT NULL DEFAULT true,
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Stores_Code" ON "Stores" ("Code");

CREATE TABLE IF NOT EXISTS "Users" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Username" text NOT NULL DEFAULT 'admin',
  "Name" text NOT NULL,
  "Phone" text NOT NULL,
  "PinHash" text NOT NULL,
  "Active" boolean NOT NULL DEFAULT true,
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_Users_Username" ON "Users" ("Username");

CREATE TABLE IF NOT EXISTS "StoreUsers" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "UserId" integer NOT NULL,
  "Role" text NOT NULL,
  "PermissionsJson" text NOT NULL DEFAULT '[]',
  "Active" boolean NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_StoreUsers_StoreId_UserId" ON "StoreUsers" ("StoreId","UserId");
CREATE INDEX IF NOT EXISTS "IX_StoreUsers_UserId" ON "StoreUsers" ("UserId");

CREATE TABLE IF NOT EXISTS "Licenses" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "LicenseId" text NOT NULL,
  "ActivationCode" text NOT NULL DEFAULT '',
  "ActivationCodeUsed" boolean NOT NULL DEFAULT false,
  "Plan" text NOT NULL,
  "Status" text NOT NULL,
  "IssuedAt" timestamptz NOT NULL DEFAULT now(),
  "ExpiresAt" timestamptz NOT NULL,
  "OriginalPrice" numeric NOT NULL,
  "FinalPrice" numeric NOT NULL,
  "DiscountCode" text NOT NULL DEFAULT '',
  "FeaturesJson" text NOT NULL DEFAULT '[]',
  "BusinessTypesJson" text NOT NULL DEFAULT '["*"]',
  "MaxUsers" integer NOT NULL DEFAULT 5,
  "Username" text NOT NULL DEFAULT 'admin',
  "InitialPassword" text NOT NULL DEFAULT '',
  "RecoveryCode" text NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Licenses_LicenseId" ON "Licenses" ("LicenseId");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Licenses_ActivationCode" ON "Licenses" ("ActivationCode") WHERE "ActivationCode" <> '';
CREATE INDEX IF NOT EXISTS "IX_Licenses_StoreId" ON "Licenses" ("StoreId");

CREATE TABLE IF NOT EXISTS "DiscountCodes" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Code" text NOT NULL,
  "Percent" integer NOT NULL,
  "FixedAmount" numeric NOT NULL,
  "MaxUses" integer NOT NULL,
  "UsedCount" integer NOT NULL DEFAULT 0,
  "ExpiresAt" timestamptz NULL,
  "Active" boolean NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DiscountCodes_Code" ON "DiscountCodes" ("Code");

CREATE TABLE IF NOT EXISTS "SyncChanges" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "UserId" integer NOT NULL,
  "Entity" text NOT NULL,
  "Operation" text NOT NULL,
  "EntityId" text NOT NULL,
  "PayloadJson" text NOT NULL DEFAULT '{}',
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_SyncChanges_StoreId_Id" ON "SyncChanges" ("StoreId","Id");

CREATE TABLE IF NOT EXISTS "UserDevices" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "UserId" integer NOT NULL,
  "DeviceId" text NOT NULL,
  "Platform" text NOT NULL,
  "Name" text NOT NULL,
  "FirstSeenAt" timestamptz NOT NULL DEFAULT now(),
  "LastSeenAt" timestamptz NOT NULL DEFAULT now(),
  "Active" boolean NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_UserDevices_StoreId_UserId_DeviceId" ON "UserDevices" ("StoreId","UserId","DeviceId");

CREATE TABLE IF NOT EXISTS "CloudRecords" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "Entity" text NOT NULL,
  "EntityId" text NOT NULL,
  "Operation" text NOT NULL DEFAULT 'UPSERT',
  "PayloadJson" text NOT NULL DEFAULT '{}',
  "SourceVersion" bigint NOT NULL DEFAULT 0,
  "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
  "UserId" integer NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_CloudRecords_StoreId_Entity_EntityId" ON "CloudRecords" ("StoreId","Entity","EntityId");

CREATE TABLE IF NOT EXISTS "PricingEntries" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PlanDays" integer NOT NULL,
  "Price" numeric NOT NULL,
  "Currency" text NOT NULL DEFAULT 'تومان',
  "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_PricingEntries_PlanDays" ON "PricingEntries" ("PlanDays");

CREATE TABLE IF NOT EXISTS "SupportTickets" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TicketCode" text NOT NULL,
  "Type" text NOT NULL DEFAULT 'SUPPORT',
  "StoreCode" text NOT NULL DEFAULT '',
  "LicenseId" text NOT NULL DEFAULT '',
  "Username" text NOT NULL DEFAULT 'admin',
  "DeviceId" text NOT NULL DEFAULT '',
  "Contact" text NOT NULL DEFAULT '',
  "Message" text NOT NULL DEFAULT '',
  "Status" text NOT NULL DEFAULT 'OPEN',
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_SupportTickets_TicketCode" ON "SupportTickets" ("TicketCode");

